pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 _number, uint64 _timestamp, uint256 _basefee1, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        uint256 _basefee2 = bound(uint256(keccak256(abi.encode(_basefee1, 1))), 0, type(uint256).max);
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);
        c.setL1BlockValues(_number, _timestamp, _basefee1, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
        vm.prank(depositor);
        c.setL1BlockValues(_number+1, _timestamp, _basefee2, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
        assertTrue(c.basefee() == _basefee2);
    }
}

