pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // Ensure we use a non-depositor account
        address nonDepositor = address(0x1234);
        vm.assume(nonDepositor != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);

        // Record initial basefee (should be 0 for a fresh contract)
        uint256 initialBasefee = c.basefee();

        // Call setL1BlockValues as non-depositor; it should revert for reference, but we catch revert
        vm.prank(nonDepositor);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setL1BlockValues.selector, _number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar));

        // General rule: after calling setL1BlockValues from non-depositor, basefee must equal initialBasefee (unchanged)
        uint256 finalBasefee = c.basefee();
        assertTrue(finalBasefee == initialBasefee, "basefee should not change when caller is not depositor");
    }
}

