pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Record state before the call
        uint64 numberBefore = c.number();
        uint64 timestampBefore = c.timestamp();
        uint256 basefeeBefore = c.basefee();
        bytes32 hashBefore = c.hash();
        uint64 sequenceNumberBefore = c.sequenceNumber();
        bytes32 batcherHashBefore = c.batcherHash();
        uint256 l1FeeOverheadBefore = c.l1FeeOverhead();
        uint256 l1FeeScalarBefore = c.l1FeeScalar();

        // Call from a non-depositor account (the test contract itself)
        vm.prank(address(0x1234));
        (bool success, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                _number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar
            )
        );

        // The call must revert because only the depositor can set values
        assertTrue(!success);

        // Verify all state variables remain unchanged
        assertTrue(c.number() == numberBefore);
        assertTrue(c.timestamp() == timestampBefore);
        assertTrue(c.basefee() == basefeeBefore);
        assertTrue(c.hash() == hashBefore);
        assertTrue(c.sequenceNumber() == sequenceNumberBefore);
        assertTrue(c.batcherHash() == batcherHashBefore);
        assertTrue(c.l1FeeOverhead() == l1FeeOverheadBefore);
        assertTrue(c.l1FeeScalar() == l1FeeScalarBefore);
    }
}

